//! Cross-language wire format for `CapabilityRef` invocations.
//!
//! See `docs/book/src/capability-abi.md` for the schema spec. This
//! module is the canonical Rust implementation that other-language
//! bindings (Go, JVM, Swift, JS) must round-trip against — the
//! `tests/golden/cap-*.cbor` corpus is generated by tests in this
//! file and re-read by every binding's wire-compat suite.
//!
//! Encoding/decoding go through `ciborium` (the same CBOR codec
//! rce-format uses for `.fg` containers), so binary output is
//! deterministic and shared across all rce-internal serialisations.

use ciborium::value::Value as CborValue;
use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Schema-version constant emitted into every encoded request.
///
/// Bumping this is a *breaking* change. Additive fields use
/// integer-keyed map entries; decoders ignore unknown keys.
pub const WIRE_SCHEMA_VERSION: u32 = 1;

// ── Error ───────────────────────────────────────────────────────────

#[derive(Debug, Error)]
pub enum WireError {
    #[error("cbor encode: {0}")]
    Encode(String),
    #[error("cbor decode: {0}")]
    Decode(String),
    #[error("wire schema: {0}")]
    Schema(String),
}

// ── Request ─────────────────────────────────────────────────────────

/// Decoded capability-invocation request. Map keys in CBOR are
/// integers (1..=8) per the spec — see `capability-abi.md`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WireRequest {
    pub capability_id: String,
    pub version: String,
    pub method: String,
    /// Method args as opaque CBOR bytes. Outer codec doesn't peek.
    pub args: Vec<u8>,
    pub effects: Vec<String>,
    pub delegation_chain: Option<Vec<u8>>,
    pub nonce: Option<[u8; 16]>,
    pub trace_id: Option<[u8; 16]>,
}

impl WireRequest {
    /// Encode to deterministic CBOR bytes.
    pub fn encode(&self) -> Result<Vec<u8>, WireError> {
        let mut entries: Vec<(CborValue, CborValue)> = Vec::with_capacity(8);
        entries.push((CborValue::Integer(1.into()), CborValue::Text(self.capability_id.clone())));
        entries.push((CborValue::Integer(2.into()), CborValue::Text(self.version.clone())));
        entries.push((CborValue::Integer(3.into()), CborValue::Text(self.method.clone())));
        entries.push((CborValue::Integer(4.into()), CborValue::Bytes(self.args.clone())));
        let effects_cbor = self
            .effects
            .iter()
            .cloned()
            .map(CborValue::Text)
            .collect::<Vec<_>>();
        entries.push((CborValue::Integer(5.into()), CborValue::Array(effects_cbor)));
        if let Some(chain) = &self.delegation_chain {
            entries.push((CborValue::Integer(6.into()), CborValue::Bytes(chain.clone())));
        }
        if let Some(n) = &self.nonce {
            entries.push((CborValue::Integer(7.into()), CborValue::Bytes(n.to_vec())));
        }
        if let Some(t) = &self.trace_id {
            entries.push((CborValue::Integer(8.into()), CborValue::Bytes(t.to_vec())));
        }
        let map = CborValue::Map(entries);
        let mut out = Vec::new();
        ciborium::ser::into_writer(&map, &mut out)
            .map_err(|e| WireError::Encode(format!("{e}")))?;
        Ok(out)
    }

    /// Decode from CBOR bytes. Unknown integer keys are tolerated for
    /// forward compatibility; unknown text keys are rejected.
    pub fn decode(bytes: &[u8]) -> Result<Self, WireError> {
        let v: CborValue = ciborium::de::from_reader(bytes)
            .map_err(|e| WireError::Decode(format!("{e}")))?;
        let map = match v {
            CborValue::Map(m) => m,
            other => {
                return Err(WireError::Schema(format!(
                    "request top level must be a map, got {other:?}"
                )));
            }
        };
        let mut capability_id: Option<String> = None;
        let mut version: Option<String> = None;
        let mut method: Option<String> = None;
        let mut args: Option<Vec<u8>> = None;
        let mut effects: Option<Vec<String>> = None;
        let mut delegation_chain: Option<Vec<u8>> = None;
        let mut nonce: Option<[u8; 16]> = None;
        let mut trace_id: Option<[u8; 16]> = None;
        for (k, val) in map {
            let key = match k {
                CborValue::Integer(i) => i,
                CborValue::Text(t) => {
                    return Err(WireError::Schema(format!(
                        "unknown text key `{t}` (only integer keys are recognised)"
                    )));
                }
                other => {
                    return Err(WireError::Schema(format!(
                        "key must be int or text, got {other:?}"
                    )));
                }
            };
            let key_i64: i128 = key.into();
            match key_i64 {
                1 => capability_id = Some(text(val, "capability_id")?),
                2 => version = Some(text(val, "version")?),
                3 => method = Some(text(val, "method")?),
                4 => args = Some(bytes_field(val, "args")?),
                5 => effects = Some(text_array(val, "effects")?),
                6 => delegation_chain = Some(bytes_field(val, "delegation_chain")?),
                7 => nonce = Some(fixed_bytes::<16>(val, "nonce")?),
                8 => trace_id = Some(fixed_bytes::<16>(val, "trace_id")?),
                _ => { /* tolerate unknown integer keys */ }
            }
        }
        Ok(WireRequest {
            capability_id: capability_id
                .ok_or_else(|| WireError::Schema("missing key 1 capability_id".into()))?,
            version: version.ok_or_else(|| WireError::Schema("missing key 2 version".into()))?,
            method: method.ok_or_else(|| WireError::Schema("missing key 3 method".into()))?,
            args: args.ok_or_else(|| WireError::Schema("missing key 4 args".into()))?,
            effects: effects.ok_or_else(|| WireError::Schema("missing key 5 effects".into()))?,
            delegation_chain,
            nonce,
            trace_id,
        })
    }
}

// ── Response ────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum WireResponse {
    Ok { result: Vec<u8> },
    Err { code: String, message: String, details: Option<Vec<u8>> },
}

impl WireResponse {
    pub fn encode(&self) -> Result<Vec<u8>, WireError> {
        let mut entries: Vec<(CborValue, CborValue)> = Vec::with_capacity(3);
        match self {
            WireResponse::Ok { result } => {
                entries.push((CborValue::Integer(1.into()), CborValue::Integer(0.into())));
                entries.push((CborValue::Integer(2.into()), CborValue::Bytes(result.clone())));
            }
            WireResponse::Err { code, message, details } => {
                entries.push((CborValue::Integer(1.into()), CborValue::Integer(1.into())));
                let mut err_entries: Vec<(CborValue, CborValue)> = Vec::with_capacity(3);
                err_entries.push((
                    CborValue::Integer(1.into()),
                    CborValue::Text(code.clone()),
                ));
                err_entries.push((
                    CborValue::Integer(2.into()),
                    CborValue::Text(message.clone()),
                ));
                if let Some(d) = details {
                    err_entries.push((
                        CborValue::Integer(3.into()),
                        CborValue::Bytes(d.clone()),
                    ));
                }
                entries.push((CborValue::Integer(3.into()), CborValue::Map(err_entries)));
            }
        }
        let map = CborValue::Map(entries);
        let mut out = Vec::new();
        ciborium::ser::into_writer(&map, &mut out)
            .map_err(|e| WireError::Encode(format!("{e}")))?;
        Ok(out)
    }

    pub fn decode(bytes: &[u8]) -> Result<Self, WireError> {
        let v: CborValue = ciborium::de::from_reader(bytes)
            .map_err(|e| WireError::Decode(format!("{e}")))?;
        let map = match v {
            CborValue::Map(m) => m,
            other => {
                return Err(WireError::Schema(format!(
                    "response top level must be a map, got {other:?}"
                )));
            }
        };
        let mut status: Option<u32> = None;
        let mut result: Option<Vec<u8>> = None;
        let mut error_map: Option<Vec<(CborValue, CborValue)>> = None;
        for (k, val) in map {
            let CborValue::Integer(i) = k else {
                return Err(WireError::Schema(format!("unknown response key {k:?}")));
            };
            let key_i64: i128 = i.into();
            match key_i64 {
                1 => {
                    let CborValue::Integer(s) = val else {
                        return Err(WireError::Schema("status must be uint".into()));
                    };
                    let s_i: i128 = s.into();
                    status = Some(s_i as u32);
                }
                2 => result = Some(bytes_field(val, "result")?),
                3 => match val {
                    CborValue::Map(m) => error_map = Some(m),
                    other => {
                        return Err(WireError::Schema(format!(
                            "error must be map, got {other:?}"
                        )));
                    }
                },
                _ => { /* tolerate forward-compat extensions */ }
            }
        }
        let status = status.ok_or_else(|| WireError::Schema("missing status".into()))?;
        match status {
            0 => {
                let result = result.ok_or_else(|| WireError::Schema("ok response missing result".into()))?;
                Ok(WireResponse::Ok { result })
            }
            1 => {
                let em = error_map
                    .ok_or_else(|| WireError::Schema("err response missing error".into()))?;
                let mut code: Option<String> = None;
                let mut message: Option<String> = None;
                let mut details: Option<Vec<u8>> = None;
                for (k, val) in em {
                    let CborValue::Integer(i) = k else { continue };
                    let key_i64: i128 = i.into();
                    match key_i64 {
                        1 => code = Some(text(val, "error.code")?),
                        2 => message = Some(text(val, "error.message")?),
                        3 => details = Some(bytes_field(val, "error.details")?),
                        _ => {}
                    }
                }
                Ok(WireResponse::Err {
                    code: code.ok_or_else(|| WireError::Schema("missing error.code".into()))?,
                    message: message
                        .ok_or_else(|| WireError::Schema("missing error.message".into()))?,
                    details,
                })
            }
            other => Err(WireError::Schema(format!("unknown status {other}"))),
        }
    }
}

// ── CBOR field decode helpers ───────────────────────────────────────

fn text(val: CborValue, field: &str) -> Result<String, WireError> {
    match val {
        CborValue::Text(t) => Ok(t),
        other => Err(WireError::Schema(format!("{field} must be text, got {other:?}"))),
    }
}

fn bytes_field(val: CborValue, field: &str) -> Result<Vec<u8>, WireError> {
    match val {
        CborValue::Bytes(b) => Ok(b),
        other => Err(WireError::Schema(format!("{field} must be bytes, got {other:?}"))),
    }
}

fn fixed_bytes<const N: usize>(val: CborValue, field: &str) -> Result<[u8; N], WireError> {
    let v = bytes_field(val, field)?;
    if v.len() != N {
        return Err(WireError::Schema(format!(
            "{field}: expected {N} bytes, got {}",
            v.len()
        )));
    }
    let mut arr = [0u8; N];
    arr.copy_from_slice(&v);
    Ok(arr)
}

fn text_array(val: CborValue, field: &str) -> Result<Vec<String>, WireError> {
    let arr = match val {
        CborValue::Array(a) => a,
        other => {
            return Err(WireError::Schema(format!(
                "{field} must be array, got {other:?}"
            )));
        }
    };
    let mut out = Vec::with_capacity(arr.len());
    for item in arr {
        out.push(text(item, field)?);
    }
    Ok(out)
}

// ── Tests ───────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_request() -> WireRequest {
        WireRequest {
            capability_id: "joulesperbit.pay.ledger".into(),
            version: "1.0.0".into(),
            method: "transfer".into(),
            args: b"\x83\x18\x2a\x18\x64\x19\x03\xe8".to_vec(), // CBOR [42, 100, 1000]
            effects: vec!["regulatory:financial".into(), "pii:read".into()],
            delegation_chain: Some(vec![0xde, 0xad, 0xbe, 0xef]),
            nonce: Some([0x11; 16]),
            trace_id: Some([0x22; 16]),
        }
    }

    #[test]
    fn request_round_trip() {
        let req = sample_request();
        let bytes = req.encode().expect("encode");
        let back = WireRequest::decode(&bytes).expect("decode");
        assert_eq!(req, back);
    }

    #[test]
    fn request_minimal_round_trip() {
        let req = WireRequest {
            capability_id: "test.cap".into(),
            version: "0.1".into(),
            method: "noop".into(),
            args: vec![],
            effects: vec![],
            delegation_chain: None,
            nonce: None,
            trace_id: None,
        };
        let bytes = req.encode().expect("encode");
        let back = WireRequest::decode(&bytes).expect("decode");
        assert_eq!(req, back);
    }

    #[test]
    fn request_tolerates_unknown_integer_keys() {
        let mut entries: Vec<(CborValue, CborValue)> = Vec::new();
        entries.push((CborValue::Integer(1.into()), CborValue::Text("c".into())));
        entries.push((CborValue::Integer(2.into()), CborValue::Text("v".into())));
        entries.push((CborValue::Integer(3.into()), CborValue::Text("m".into())));
        entries.push((CborValue::Integer(4.into()), CborValue::Bytes(vec![])));
        entries.push((CborValue::Integer(5.into()), CborValue::Array(vec![])));
        entries.push((CborValue::Integer(99.into()), CborValue::Text("future".into())));
        let map = CborValue::Map(entries);
        let mut bytes = Vec::new();
        ciborium::ser::into_writer(&map, &mut bytes).unwrap();
        let req = WireRequest::decode(&bytes).expect("forward-compat decode");
        assert_eq!(req.capability_id, "c");
    }

    #[test]
    fn response_ok_round_trip() {
        let resp = WireResponse::Ok {
            result: vec![0x42, 0x43, 0x44],
        };
        let bytes = resp.encode().expect("encode");
        let back = WireResponse::decode(&bytes).expect("decode");
        assert_eq!(resp, back);
    }

    #[test]
    fn response_err_round_trip() {
        let resp = WireResponse::Err {
            code: "insufficient_funds".into(),
            message: "balance < amount".into(),
            details: Some(vec![0xa1, 0x01, 0x18, 0x2a]), // CBOR {1: 42}
        };
        let bytes = resp.encode().expect("encode");
        let back = WireResponse::decode(&bytes).expect("decode");
        assert_eq!(resp, back);
    }

    #[test]
    fn response_err_no_details_round_trip() {
        let resp = WireResponse::Err {
            code: "denied".into(),
            message: "policy".into(),
            details: None,
        };
        let bytes = resp.encode().expect("encode");
        let back = WireResponse::decode(&bytes).expect("decode");
        assert_eq!(resp, back);
    }

    #[test]
    fn malformed_top_level_fails() {
        // CBOR for a single integer (not a map).
        let bytes = vec![0x18, 0x2a]; // 42
        let r = WireRequest::decode(&bytes);
        assert!(r.is_err());
    }
}
